def parse_exact_item_line(line, item_text):
    if line.endswith("\r\n"):
        ending = "\r\n"
        body = line[:-2]
    elif line.endswith("\n") or line.endswith("\r"):
        ending = line[-1]
        body = line[:-1]
    else:
        ending = ""
        body = line
    item_position = body.find(item_text)
    if item_position < 0 or body.find(item_text, item_position + len(item_text)) >= 0:
        return None
    suffix = body[item_position + len(item_text):]
    if suffix.strip():
        return None
    return {"prefix": body[:item_position], "suffix": suffix, "ending": ending}
